input.command:
awk -F'|' '
$11=="HOLD"{
  key=$1; failed=$4+0; test=$5; rcpt=$6; rstate=$8; rart=$9; bill=$10; reason=$12;
  missing = (rcpt=="missing") || (reason ~ /missing input/);
  if(missing){ g5=g5" "key; g5n++ }
  else {
    if(failed>0){ g1=g1" "key; g1n++ }
    if(test!="missing" && rcpt!="missing" && test!=rcpt){ g2=g2" "key; g2n++ }
    if(rstate!="APPROVED" || rart!=rcpt){ g3=g3" "key; g3n++ }
  }
  if(bill=="yes"){ g4=g4" "key; g4n++ }
}
END{
  print "G1 failed-assertions>0 ("g1n"):"g1;
  print "G2 test!=receipt artifact ("g2n"):"g2;
  print "G3 transfer review not APPROVED for receipt artifact ("g3n"):"g3;
  print "G4 billing hold active ("g4n"):"g4;
  print "G5 missing input ("g5n"):"g5;
  print "total HOLD rows: " (g1n>0?"":"") 
}' /app/register_rows.psv
echo "HOLD count:"; awk -F'|' '$11=="HOLD"' /app/register_rows.psv | wc -l
